export interface AnalyticsPayload {
  page?: string
  path?: string
  url?: string
  timestamp?: number
  [key: string]: unknown
}

export async function logPageView(page: string = '/') {
  // In a production application, this would send an event to an analytics provider
  console.log(`[Analytics] Page view logged: ${page}`)
}

export async function trackPageView(page: string = '/') {
  console.log(`[Analytics] Page view tracked: ${page}`)
}

export const analytics = {
  logPageView,
  trackPageView,
  track: async (event: string, data?: AnalyticsPayload) => {
    console.log(`[Analytics] Event tracked: ${event}`, data)
  },
}

export const analyticsService = {
  logPageView,
  trackPageView,
  log: logPageView,
  track: analytics.track,
}

export default analyticsService

